# Check if id_provider is not set to ad (Active Directory) which makes start_tls not applicable, note the -v option to invert the grep. # Try to find [domain/..] and ldap_tls_reqcert in sssd.conf, if it exists, set to 'demand' # if ldap_tls_reqcert isn't here, add it # if [domain/..] doesn't exist, add it here for default domain if grep -qvzosP $AD_REGEX $SSSD_CONF; then if grep -qzosP $LDAP_REGEX $SSSD_CONF; then
sed -i "s#ldap_tls_reqcert[^(
)]*#ldap_tls_reqcert = demand#" $SSSD_CONF elif grep -qs $DOMAIN_REGEX $SSSD_CONF; then sed -i "/$DOMAIN_REGEX/a ldap_tls_reqcert = demand" $SSSD_CONF else if test -f "$SSSD_CONF"; then echo -e "[domain/default]
ldap_tls_reqcert = demand" >> $SSSD_CONF else echo "Config file '$SSSD_CONF' doesnt exist, not remediating, assuming non-applicability." >&2 fi fi fi
readarray -t SSSD_CONF_D_FILES < <(find /etc/sssd/conf.d/ -name "*.conf") for SSSD_CONF_D_FILE in "${SSSD_CONF_D_FILES[@]}"; do sed -i "s#ldap_tls_reqcert[^(
)]*#ldap_tls_reqcert = demand#" "$SSSD_CONF_D_FILE" done
else >&2 echo 'Remediation is not applicable, nothing was done' fi

# Remediation is applicable only in certain platforms if ( rpm --quiet -q kernel || rpm --quiet -q kernel-uek ) && rpm --quiet -q sssd-common; then
SSSD_CONF="/etc/sssd/sssd.conf" LDAP_REGEX='[[:space:]]*\[domain/[^]]*]([^(
)]*(
)+)+?[[:space:]]*ldap_id_use_start_tls' AD_REGEX='[[:space:]]*\[domain/[^]]*]([^(
)]*(
)+)+?[[:space:]]*id_provider[[:space:]]*=[[:space:]]*((?i)ad)[[:space:]]*$' DOMAIN_REGEX="[[:space:]]*\[domain/[^]]*]"
# Check if id_provider is not set to ad (Active Directory) which makes start_tls not applicable, note the -v option to invert the grep. # Try to find [domain/..] and ldap_id_use_start_tls in sssd.conf, if it exists, set to 'true' # if ldap_id_use_start_tls isn't here, add it # if [domain/..] doesn't exist, add it here for default domain if grep -qvzosP $AD_REGEX $SSSD_CONF; then if grep -qzosP $LDAP_REGEX $SSSD_CONF; then
sed -i "s#ldap_id_use_start_tls[^(
)]*#ldap_id_use_start_tls = true#" $SSSD_CONF elif grep -qs $DOMAIN_REGEX $SSSD_CONF; then sed -i "/$DOMAIN_REGEX/a ldap_id_use_start_tls = true" $SSSD_CONF else if test -f "$SSSD_CONF"; then echo -e "[domain/default]
ldap_id_use_start_tls = true" >> $SSSD_CONF else echo "Config file '$SSSD_CONF' doesnt exist, not remediating, assuming non-applicability." >&2 fi fi fi
readarray -t SSSD_CONF_D_FILES < <(find /etc/sssd/conf.d/ -name "*.conf") for SSSD_CONF_D_FILE in "${SSSD_CONF_D_FILES[@]}"; do sed -i "s#ldap_id_use_start_tls[^(
)]*#ldap_id_use_start_tls = true#" "$SSSD_CONF_D_FILE" done
else >&2 echo 'Remediation is not applicable, nothing was done' fi

include install_usbguard

class install_usbguard {
  package { 'usbguard':
    ensure => 'installed',
  }
}

include enable_usbguard

class enable_usbguard {
  service {'usbguard':
    enable => true,
    ensure => 'running',
  }
}

include install_audispd-plugins

class install_audispd-plugins {
  package { 'audispd-plugins':
    ensure => 'installed',
  }
}

include install_audit

class install_audit {
  package { 'audit':
    ensure => 'installed',
  }
}

include enable_auditd

class enable_auditd {
  service {'auditd':
    enable => true,
    ensure => 'running',
  }
}

# Remediation is applicable only in certain platforms if ( rpm --quiet -q kernel || rpm --quiet -q kernel-uek ) && rpm --quiet -q audit; then
find -P /etc/audit/ -maxdepth 1 -perm /u+xs,g+xws,o+xwrt -type f -regextype posix-extended -regex '^.*audit(\.rules|d\.conf)$' -exec chmod u-xs,g-xws,o-xwrt {} \;
find -P /etc/audit/rules.d/ -maxdepth 1 -perm /u+xs,g+xws,o+xwrt -type f -regextype posix-extended -regex '^.*\.rules$' -exec chmod u-xs,g-xws,o-xwrt {} \;
else >&2 echo 'Remediation is not applicable, nothing was done' fi

# Remediation is applicable only in certain platforms if ( rpm --quiet -q kernel || rpm --quiet -q kernel-uek ); then
find -P /etc/audit/rules.d/ -maxdepth 1 -perm /u+xs,g+xwrs,o+xwrt -type f -regextype posix-extended -regex '^.*rules$' -exec chmod u-xs,g-xwrs,o-xwrt {} \;
else >&2 echo 'Remediation is not applicable, nothing was done' fi
